custom_css:
/* ============================================================
   《不可译》 Untranslatable · 夜航辞典
   为 amber 独家定制 · 2026
   概念：整个酒馆是一本收录「不可译之词」的辞典，
        每一层楼是一页词条，重roll是另一种译法，
        思维链是无需言说之事（Tacenda）。
   技术致谢：三段式卡片思路参考 @NAKARI / @lazyalie，
        输入框占位符打字机 @墨千尾，最后一楼间距修复 @Serein。
   装饰全部使用纯CSS/内嵌SVG，不依赖图床，永不裂图。
   ============================================================ */

@import url("https://fontsapi.zeoseven.com/292/main/result.css");

body {
    font-family: "LXGW WenKai", "Noto Serif SC", serif;
    font-weight: normal;
}

/* ============================================================
   0. 甲方调整区 —— 想改的都在这里
   ============================================================ */
:root {
    /* 卡片底色（最后一个数字是透明度，0~1，越小越透） */
    --char卡片底色: rgba(11, 13, 17, 0.55);
    --user卡片底色: rgba(22, 18, 14, 0.5);
    --卡片模糊: 6px;          /* 卡片毛玻璃强度，0px 为完全清透 */

    /* 两支点缀色 */
    --月光银: rgba(174, 184, 196, 1);    /* Mångata */
    --叶隙金: rgba(196, 173, 139, 1);    /* Komorebi */

    /* 文本 */
    --正文行高: 1.9;
    --文本两侧间距: 16px;

    /* 文案 */
    --输入框文案: "Iktsuarpok —— 一次次张望，等一句尚未抵达的话";
    --思维链标题: "Tacenda ｜ 拉丁语 · 有些思索，无需言说";
    --翻页左文案: "前一种译法";
    --翻页右文案: "另一种译法";

    /* 布局 */
    --抽屉高度: 39px;    /* 顶栏菜单面板与顶栏有空隙时调这个 */
}


/* ============================================================
   1. 全局布局与基础
   （不设置 body 背景 —— 请在酒馆背景页放你自己的图，
     卡片是半透明的，任何背景都透得出来）
   ============================================================ */

/* 隐藏滚动条（手机）；桌面端细银线 */
::-webkit-scrollbar { width: 3px; background: transparent; }
::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--月光银), transparent 55%) !important;
    border: none !important; box-shadow: none !important;
}
@media screen and (max-width: 700px) {
    ::-webkit-scrollbar { display: none; }
}

/* 选中文本 */
::selection { background: color-mix(in srgb, var(--叶隙金), transparent 55%); }

/* 禁止文本域拉伸 */
textarea, #send_textarea { resize: none; }

/* 弹窗阴影去除 */
#select_chat_popup, .popup, .popper-modal { box-shadow: none !important; }

/* 背景菜单区域 */
#bg-header-fixed, #bg_tabs { background: none; }
#backgrounds-button * { box-shadow: none; }

/* 聊天主区域 */
#chat {
    border: none !important;
    max-height: calc(100dvh + var(--bottomFormBlockSize));
    height: calc(100dvh + var(--bottomFormBlockSize));
    padding: 50px 10px 130px 10px !important;
    /* 上下柔和渐隐 */
    mask: linear-gradient(to bottom,
        transparent 0%, black 4%, black 96%, transparent 100%);
    -webkit-mask: linear-gradient(to bottom,
        transparent 0%, black 4%, black 96%, transparent 100%);
}

/* 遮罩层 */
#sheld {
    top: var(--bottomFormBlockSize);
    height: calc(100dvh - var(--bottomFormBlockSize));
    max-height: calc(100dvh - var(--bottomFormBlockSize));
    min-height: calc(100dvh - var(--bottomFormBlockSize));
}

/* 抽屉面板容器 */
.drawer-content {
    background: rgba(10, 12, 16, 0.92) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 8px 8px 20px 8px !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    top: var(--抽屉高度) !important;
}

/* 左右侧边栏 */
#left-nav-panel, #right-nav-panel {
    height: calc(100dvh - var(--topBarBlockSize)) !important;
    top: var(--抽屉高度) !important;
}


/* ============================================================
   2. 消息主体 —— 词条卡片
   ============================================================ */

/* 修复最后一条消息间距｜@Serein */
.mes.last_mes > *:has(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

/* 卡片：一页词条 */
.mes {
    position: relative !important;
    overflow: visible !important;
    display: flex !important;
    flex-direction: column !important;

    background: var(--char卡片底色) !important;
    backdrop-filter: blur(var(--卡片模糊)) !important;
    -webkit-backdrop-filter: blur(var(--卡片模糊)) !important;
    border: 1px solid color-mix(in srgb, var(--月光银), transparent 86%) !important;
    border-top: 1px solid color-mix(in srgb, var(--月光银), transparent 62%) !important;
    border-radius: 2px !important;
    box-shadow: none !important;

    padding: 14px var(--文本两侧间距) 38px var(--文本两侧间距) !important;
    margin: 14px auto 26px auto !important;
    width: 100%;
}

.mes[is_user="true"] {
    background: var(--user卡片底色) !important;
}

.last_mes { margin-bottom: 70px !important; }

/* --- 词头：九个不可译之词，逐楼轮转 --- */
.mes::before {
    content: "Komorebi ｜ 日语 · 叶隙间漏下的光";
    display: block;
    font-size: 12px;
    letter-spacing: 0.4px;
    color: color-mix(in srgb, var(--月光银), transparent 12%);
    padding: 0 44px 8px 0;    /* 右侧避开小头像 */
    margin-bottom: 10px;
    border-bottom: 1px solid color-mix(in srgb, var(--月光银), transparent 82%);
}
#chat .mes:nth-of-type(9n+1)::before { content: "Komorebi ｜ 日语 · 叶隙间漏下的光"; }
#chat .mes:nth-of-type(9n+2)::before { content: "Mångata ｜ 瑞典语 · 月光铺在海上的路"; }
#chat .mes:nth-of-type(9n+3)::before { content: "Cafuné ｜ 葡萄牙语 · 指尖轻轻穿过爱人的头发"; }
#chat .mes:nth-of-type(9n+4)::before { content: "Fernweh ｜ 德语 · 对未曾抵达的远方害了乡愁"; }
#chat .mes:nth-of-type(9n+5)::before { content: "Forelsket ｜ 挪威语 · 坠入爱河最初的眩晕"; }
#chat .mes:nth-of-type(9n+6)::before { content: "Hiraeth ｜ 威尔士语 · 思念一个再也回不去的地方"; }
#chat .mes:nth-of-type(9n+7)::before { content: "Kilig ｜ 他加禄语 · 心动时浑身微微的颤栗"; }
#chat .mes:nth-of-type(9n+8)::before { content: "Aparima ｜ 大溪地语 · 以双手起舞，诉说不可说的故事"; }
#chat .mes:nth-of-type(9n+9)::before { content: "Iktsuarpok ｜ 因纽特语 · 一次次出门张望，盼一个人来"; }

/* user 楼层词头右对齐，像同一本辞典的另一只手写的 */
.mes[is_user="true"]::before {
    text-align: right;
    padding: 0 0 8px 44px;
    opacity: 0.75;
}
.mes[is_user="true"] .avatar { right: auto !important; left: 12px !important; }

/* --- 小头像：卡片右上角一枚圆章 --- */
.mesAvatarWrapper { position: static !important; }
.mes .avatar {
    position: absolute !important;
    top: 10px !important;
    right: 12px !important;
    width: 30px !important;
    height: 30px !important;
    opacity: 0.95 !important;
    pointer-events: none;
}
.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
    border: 1px solid color-mix(in srgb, var(--月光银), transparent 45%) !important;
    box-shadow: none !important;
}

/* --- 消息块 --- */
.mes_block {
    overflow: visible !important;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* --- 名字与收录行 --- */
.mes .ch_name { display: flex !important; }
.mes .ch_name .alignItemsBaseline {
    display: flex !important;
    align-items: baseline !important;
    flex-wrap: wrap;
    gap: 6px;
    width: 100%;
}
.name_text {
    font-size: 13px !important;
    font-weight: normal !important;
    letter-spacing: 1px;
    color: rgba(236, 233, 228, 0.95) !important;
}
.timestamp {
    font-size: 9.5px;
    color: color-mix(in srgb, var(--月光银), transparent 30%) !important;
    opacity: 1 !important;
}
.timestamp::before { content: "· 收录于 "; }

/* --- 检索元数据三件套：词条号 / 释义字数 / 检索耗时 --- */
.mesIDDisplay, .tokenCounterDisplay, .mes_timer {
    font-size: 9px !important;
    font-weight: normal !important;
    opacity: 1 !important;
    color: color-mix(in srgb, var(--月光银), transparent 38%) !important;
}
.mes .mesIDDisplay { order: 1; margin-left: auto; }
.mes .tokenCounterDisplay { order: 2; margin-left: 5px; }
.mes .mes_timer { order: 3; margin-left: 5px; }
.mesIDDisplay::before { content: "词条 No."; }
.tokenCounterDisplay::before { content: "释义 "; }
.tokenCounterDisplay::after { content: " 字"; }
.mes_timer::before { content: "检索 "; }

/* --- 正文 --- */
.mes_text {
    text-align: justify !important;
    line-height: var(--正文行高) !important;
    letter-spacing: 0.3px;
    margin: 0 !important;
    padding: 10px 0 0 0 !important;
}
.mes p:not(:last-child) { margin-bottom: 1.3em !important; }

/* 引号内对白：叶隙金 */
.mes q {
    background: none !important;
    color: var(--叶隙金) !important;
}
/* 斜体心声：月光银 */
.mes_text em {
    color: color-mix(in srgb, var(--月光银), transparent 12%);
}

/* --- Markdown 元素 --- */
.mes ul, .mes ol { padding-left: 1em !important; }

/* 引用块：辞典页边注 */
blockquote {
    position: relative !important;
    background: rgba(255, 255, 255, 0.04) !important;
    border: none !important;
    border-left: 2px solid color-mix(in srgb, var(--叶隙金), transparent 30%) !important;
    border-radius: 0 !important;
    padding: 10px 14px !important;
    margin: 16px 0 !important;
}

/* 代码 */
code {
    font-family: inherit;
    font-size: 0.92em;
    background: rgba(255, 255, 255, 0.05) !important;
    border: none;
    border-radius: 2px;
    color: color-mix(in srgb, var(--月光银), transparent 15%) !important;
    padding: 1px 6px !important;
}
pre code {
    display: block;
    padding: 10px 14px !important;
    background: rgba(0, 0, 0, 0.35) !important;
    border: 1px solid color-mix(in srgb, var(--月光银), transparent 80%) !important;
    border-radius: 2px !important;
    line-height: 1.6 !important;
}
pre code * { color: rgba(210, 212, 216, 0.9) !important; }

/* --- 分割线：Mångata，月亮铺在海上的路 --- */
hr {
    position: relative;
    border: none !important;
    height: 6px !important;
    margin: 20px 0 !important;
    background:
        radial-gradient(circle,
            color-mix(in srgb, var(--月光银), transparent 15%) 0 1px,
            transparent 1.8px)
        0 50% / 11px 6px repeat-x !important;
    -webkit-mask: linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent);
    mask: linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent);
    opacity: 0.9 !important;
}

/* --- 消息编辑按钮：卡片右下角 --- */
.mes_buttons, .extraMesButtons { overflow: visible !important; }
.mes_buttons {
    position: absolute !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    bottom: 9px !important;
    right: 12px !important;
    gap: 8px;
    z-index: 100;
    opacity: 1 !important;
    padding: 0;
}
.mes_button {
    opacity: 0.65 !important;
    color: var(--月光银) !important;
    font-size: 12px !important;
}
.mes_buttons .fa-pencil::before,
.mes_buttons .fa-ellipsis::before {
    font-size: 10.5px !important;
    font-weight: normal;
    font-family: "LXGW WenKai", serif;
    letter-spacing: 1px;
}
.mes_buttons .fa-pencil::before { content: "校订"; }
.mes_buttons .fa-ellipsis::before { content: "批注"; }

/* 省略号菜单 */
.extraMesButtons { position: relative !important; gap: 7px; }
.extraMesButtons > div {
    opacity: 1 !important;
    color: rgba(220, 222, 226, 0.9);
    padding: 4px 6px;
    border-radius: 2px !important;
    background: rgba(16, 18, 22, 0.95) !important;
    border: 1px solid color-mix(in srgb, var(--月光银), transparent 75%) !important;
}

/* 编辑中按钮 */
.mes_edit_buttons {
    position: absolute !important;
    gap: 8px;
    bottom: 36px;
    left: 50% !important;
    transform: translateX(-50%) !important;
    z-index: 100;
}
.mes_edit_buttons .menu_button { opacity: 1; border-color: var(--月光银); }

/* 编辑文本域 */
.mes .edit_textarea {
    background: rgba(0, 0, 0, 0.3) !important;
    border: 1px solid color-mix(in srgb, var(--月光银), transparent 75%) !important;
    border-radius: 2px !important;
}

/* --- 思维链：Tacenda，无需言说之事 --- */
.mes_reasoning_details {
    position: relative;
    margin: 12px 0 6px 0;
    border: none;
    padding: 0;
}
.mes_reasoning_header {
    position: relative !important;
    padding: 4px 0 !important;
    background: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    margin: 0;
}
.mes_reasoning_header_title { font-size: 0 !important; }
.mes_reasoning_header_title::before {
    content: var(--思维链标题);
    font-size: 10.5px;
    letter-spacing: 0.5px;
    font-style: italic;
    color: color-mix(in srgb, var(--月光银), transparent 22%);
}
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning {
    position: relative !important;
    background: rgba(255, 255, 255, 0.03) !important;
    border: none !important;
    border-left: 1px solid color-mix(in srgb, var(--月光银), transparent 55%) !important;
    border-radius: 0 !important;
    font-style: italic;
    font-size: 0.92em;
    color: color-mix(in srgb, var(--月光银), transparent 15%);
    padding: 10px 14px !important;
    margin-top: 4px;
}

/* --- 翻页：另一种译法 --- */
.swipeRightBlock { display: contents !important; }
.mes .swipe_left, .mes .swipe_right {
    position: absolute !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    height: 24px !important;
    padding: 0 10px !important;
    background: none !important;
    border: none !important;
    border-bottom: 1px solid color-mix(in srgb, var(--月光银), transparent 55%) !important;
    border-radius: 0 !important;
    font-family: inherit !important;
    font-size: 10px !important;
    opacity: 1 !important;
    bottom: 6px !important;
    transition: all 0.4s ease !important;
}
.mes .swipe_left::before, .mes .swipe_right::before {
    letter-spacing: 2px;
    font-weight: normal;
    font-family: "LXGW WenKai", serif;
    color: color-mix(in srgb, var(--月光银), transparent 20%) !important;
}
.mes .swipe_left::before { content: var(--翻页左文案); }
.mes .swipe_right::before { content: var(--翻页右文案); }
.mes .swipe_left { left: 12px; }
.mes .swipe_right { left: 110px; right: auto !important; }
.mes .swipe_left:active, .mes .swipe_right:active {
    transform: translateY(3px) !important;
    opacity: 0.4 !important;
}

/* 译法计数 */
.mes .swipes-counter {
    position: absolute !important;
    font-size: 9px !important;
    color: color-mix(in srgb, var(--月光银), transparent 30%);
    bottom: 11px !important;
    left: 210px;
    opacity: 1 !important;
    z-index: 100;
}
.mes .swipes-counter::before { content: "译 "; }

/* --- 消息删除勾选框 --- */
.del_checkbox {
    position: absolute !important;
    opacity: 1 !important;
    z-index: 100;
    top: 12px;
    left: 14px !important;
}

/* 隐藏最后的小系统气泡 */
#chat > div.mes.smallSysMes.last_mes.fade { display: none !important; }


/* ============================================================
   3. 顶栏
   ============================================================ */
#top-bar, body.no-blur #top-bar {
    background: none !important;
    box-shadow: none !important;
    border: none !important;
}
#top-settings-holder { background: none !important; height: 39px; }

/* 打开抽屉时给顶栏铺底 */
body:has(.drawer-icon.openIcon) #top-settings-holder {
    background: rgba(10, 12, 16, 0.96) !important;
}

/* 顶部图标：平时半隐的银色，打开时亮起 */
.drawer-icon {
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    font-size: 15px;
    color: color-mix(in srgb, var(--月光银), transparent 20%) !important;
    opacity: 0.45 !important;
    transition: opacity 0.3s ease !important;
}
body:has(.drawer-icon.openIcon) .drawer-icon { opacity: 0.8 !important; }
.drawer-icon.openIcon {
    opacity: 1 !important;
    color: #ffffff !important;
}
.drawer-icon.openIcon::after {
    content: "" !important;
    position: absolute !important;
    bottom: 3px !important;
    width: 26px !important;
    height: 1.5px !important;
    background: var(--月光银) !important;
}


/* ============================================================
   4. 底部输入区 —— 等待中的词（Iktsuarpok）
   ============================================================ */
:root {
    --上间距: 12px;
    --下间距: 11px;
    --输入框字号: 13px;
    --输入框行高: 1.4;
    --最小高度: calc(var(--上间距) + var(--下间距) + (var(--输入框字号) * var(--输入框行高)));
}

/* 底栏悬浮定位 */
#form_sheld { position: absolute; bottom: 0px; }

/* 布局：输入框一行，按钮一行 */
#nonQRFormItems {
    display: grid !important;
    grid-template-columns: auto 1fr auto !important;
    align-items: center !important;
    position: relative;
}
#send_textarea {
    grid-row: 1 / 2 !important;
    grid-column: 1 / 4 !important;
    width: 100% !important;
    margin-bottom: 12px !important;
}
#leftSendForm {
    grid-row: 2 / 3 !important;
    grid-column: 1 / 2 !important;
    justify-content: center !important;
    align-items: center !important;
}
#rightSendForm {
    grid-row: 2 / 3 !important;
    grid-column: 3 / 4 !important;
    justify-content: center !important;
    align-items: center !important;
}

/* 输入框容器 */
#send_form, body.no-blur #send_form {
    width: 100%;
    margin: 0 auto;
    background: rgba(10, 12, 16, 0.78) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: none !important;
    border-top: 1px solid color-mix(in srgb, var(--月光银), transparent 72%) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 8px 15px 10px 15px !important;
}

/* 文本输入域 */
#send_textarea {
    clip-path: none !important;
    background: rgba(255, 255, 255, 0.055) !important;
    border: none !important;
    border-bottom: 1px solid color-mix(in srgb, var(--月光银), transparent 65%) !important;
    border-radius: 2px !important;
    padding: var(--上间距) 16px var(--下间距) 16px !important;
    margin-bottom: 10px !important;
    line-height: var(--输入框行高) !important;
    font-size: var(--输入框字号);
    min-height: var(--最小高度) !important;
    box-shadow: none !important;
}

/* 底部按钮 */
.fa-bars, #extensionsMenuButton, .fa-paper-plane, .fa-circle-stop {
    display: flex;
    align-items: center !important;
    justify-content: center !important;
    opacity: 1 !important;
    border-radius: 50%;
    width: 35px !important;
    height: 35px !important;
    font-size: 17px !important;
    transition: all 0.3s ease !important;
    color: color-mix(in srgb, var(--月光银), transparent 10%) !important;
}
.fa-paper-plane { font-size: 19px !important; color: var(--叶隙金) !important; }
.fa-circle-stop { font-size: 19px !important; }
.fa-bars:active, #extensionsMenuButton:active {
    transform: translateY(3px);
    opacity: 0.5 !important;
}

/* --- 占位符：打字机（技术参考 @墨千尾） --- */
#send_textarea::placeholder { color: transparent; opacity: 0 !important; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--输入框文案);
    position: absolute;
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: clip;
    font-size: 10.5px;
    letter-spacing: 0.5px;
    color: color-mix(in srgb, var(--月光银), transparent 40%) !important;
    top: calc(var(--最小高度) / 2 + 1px);
    left: 50%;
    transform: translate(-50%, -50%);
    width: 0;
    max-width: fit-content;
    border-right: 1.5px solid color-mix(in srgb, var(--月光银), transparent 40%);
    animation:
        placeholderTyping 6s steps(24) infinite alternate,
        placeholderCursorBlink 1.5s infinite;
}
@keyframes placeholderTyping {
    0% { width: 0; }
    40%, 100% { width: 30em; }
}
@keyframes placeholderCursorBlink {
    50% { border-color: transparent; }
}
/* 聚焦时隐藏｜@Serein */
