    background: color-mix(in srgb, var(--月光银), transparent 55%) !important;
    border: none !important;
    box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
    appearance: none;
    width: 13px;
    height: 13px;
    border-radius: 50%;
    border: none !important;
    box-shadow: none !important;
    background: radial-gradient(circle,
        var(--叶隙金) 0 34%,
        color-mix(in srgb, var(--叶隙金), transparent 72%) 55%,
